from __future__ import annotations

import base64
import json
import os
import re
import subprocess
import sys
from datetime import date, datetime
from decimal import Decimal
from pathlib import Path
from typing import Any

READ_ONLY_PREFIXES = ("SELECT", "WITH", "SHOW", "DESC", "DESCRIBE", "EXPLAIN")


def env_int(name: str, default: int) -> int:
    try:
        return int(os.getenv(name, str(default)))
    except (TypeError, ValueError):
        return default


def skill_root_dir() -> Path:
    """本技能自身的根目录。

    从 __file__ 推导，不读环境变量：脚本就在自己的 skill 目录内，这是唯一
    不依赖宿主注入、且在本地与沙箱容器里都成立的解析方式。此前这里有一条
    env -> DATAAGENT_ENABLED_SKILL_ROOTS -> __file__ 的三层回落链，三个分支
    在所有已知部署下都解析到同一个目录。
    """
    return Path(__file__).resolve().parents[1]


def metadata_cli_bin() -> str:
    return str(skill_root_dir() / "bin" / "odw-cli")


def metadata_cli_command(subcommand: str, **options: Any) -> list[str]:
    cli_path = Path(metadata_cli_bin())
    if not cli_path.is_file():
        raise RuntimeError(
            f"metadata cli 不存在: {cli_path}。请先由用户自行安装到该路径后再重试。"
        )

    # 部署时 bind mount 可能丢失执行位，退回 sh 直读脚本即可继续运行。
    command = [str(cli_path)] if os.access(cli_path, os.X_OK) else ["sh", str(cli_path)]
    command.append(str(subcommand).strip())

    for key, value in options.items():
        if value is None:
            continue
        text = str(value).strip()
        if not text:
            continue
        command.extend([f"--{str(key).replace('_', '-')}", text])

    return command


def runtime_data_scope_header() -> str:
    configured = str(
        os.getenv("ODW_AGENT_DATA_SCOPE_HEADER")
        or os.getenv("DATAAGENT_DATA_SCOPE_HEADER")
        or ""
    ).strip()
    if configured:
        return configured

    raw_scope = str(os.getenv("DATAAGENT_DATA_SCOPE_JSON") or "").strip()
    if not raw_scope:
        return ""
    try:
        parsed = json.loads(raw_scope)
    except json.JSONDecodeError:
        return ""
    if not isinstance(parsed, dict) or not parsed.get("allowed_scopes"):
        return ""
    payload = json.dumps(parsed, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return base64.urlsafe_b64encode(payload.encode("utf-8")).decode("ascii").rstrip("=")


def serializable_value(value: Any) -> Any:
    if value is None or isinstance(value, (int, float, str, bool)):
        return value
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    return str(value)


def serializable_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [
        {str(key): serializable_value(val) for key, val in dict(row).items()}
        for row in rows
    ]


def print_json(payload: dict[str, Any]):
    print(json.dumps(payload, ensure_ascii=False, indent=2))


def error_payload(kind: str, message: str, **extra: Any) -> dict[str, Any]:
    payload = {"kind": kind, "error": message}
    payload.update(extra)
    return payload


def ensure_read_only(sql: str):
    statement = str(sql or "").strip()
    if not statement:
        raise ValueError("SQL 为空")
    upper = statement.lstrip().upper()
    if not upper.startswith(READ_ONLY_PREFIXES):
        raise ValueError("仅允许只读 SQL")
    if re.search(r"(^|\\s)(INSERT|UPDATE|DELETE|DROP|TRUNCATE|ALTER|CREATE|REPLACE)\\b", upper):
        raise ValueError("检测到非只读关键字")

from __future__ import annotations

"""
只读 SQL 执行代理 — 把交互式查询转发到 backend-agent-api 的受治理通道。

dataagent-backend 不直连任何业务数据库：只读校验、limit/字节守卫、
数据范围隔离与数据源凭据全部由 Java 侧 `/v1/ai/query/read` 权威执行，
本模块仅做参数钳制、请求转发与错误归一。
"""

import logging
import os
from typing import Any

import httpx

from core.data_scope import runtime_data_scope_header

logger = logging.getLogger(__name__)

DEFAULT_LIMIT = 100
MAX_LIMIT = 1000
DEFAULT_TIMEOUT_SECONDS = 30
MAX_TIMEOUT_SECONDS = 120

DATA_SCOPE_HEADER_NAME = "X-Agent-Data-Scope"


class QueryProxyConfigError(RuntimeError):
    """执行通道未配置（缺少 base url 或服务令牌）。"""


class QueryProxyUpstreamError(RuntimeError):
    def __init__(self, message: str, *, status_code: int):
        super().__init__(message)
        self.status_code = status_code


def _ai_base_url() -> str:
    raw = str(os.getenv("ODW_BACKEND_BASE_URL") or "").strip().rstrip("/")
    if not raw:
        return ""
    # 与 odw-cli 一致：兼容旧值 /api/v1/ai/metadata，规范化到 AI 根路径。
    if raw.endswith("/metadata"):
        return raw[: -len("/metadata")]
    return raw


def _service_token() -> str:
    return str(os.getenv("ODW_AGENT_SERVICE_TOKEN") or "").strip()


def _service_token_header_name() -> str:
    return str(os.getenv("ODW_AGENT_SERVICE_TOKEN_HEADER_NAME") or "").strip() or "X-Agent-Service-Token"


def clamp_limit(value: Any) -> int:
    try:
        limit = int(value)
    except (TypeError, ValueError):
        return DEFAULT_LIMIT
    return max(1, min(limit, MAX_LIMIT))


def clamp_timeout_seconds(value: Any) -> int:
    try:
        timeout = int(value)
    except (TypeError, ValueError):
        return DEFAULT_TIMEOUT_SECONDS
    return max(1, min(timeout, MAX_TIMEOUT_SECONDS))


def _result_state(error: str | None, row_count: int) -> str:
    if error:
        return "failed"
    if row_count <= 0:
        return "empty_result"
    return "success"

@schedule_router.post("/{schedule_id}/logs", response_model=MessageScheduleLogPageResponse)
def api_list_message_schedule_logs(schedule_id: str, payload: MessageScheduleLogsQueryRequest, request: Request):
    store = _get_store()
    schedule = store.get_message_schedule(schedule_id, context=_request_context(request))
    if not schedule:
        raise HTTPException(status_code=404, detail="Message schedule not found")
    page_payload = store.list_message_schedule_logs(
        schedule_id=schedule_id,
        page=payload.page,
        page_size=payload.page_size,
    )
    return MessageScheduleLogPageResponse.model_validate(
        {
            "schedule_id": schedule_id,
            "page": int(page_payload.get("page") or payload.page),
            "page_size": int(page_payload.get("page_size") or payload.page_size),
            "total": int(page_payload.get("total") or 0),
            "list": page_payload.get("items") or [],
        }
    )


@query_router.post("/execute")
async def api_execute_readonly_query(http_request: Request, request: ExecuteQueryRequest):
    context = _request_context(http_request)

    sql = str(request.sql or "").strip()
    database = str(request.database or "").strip()
    if not sql:
        raise HTTPException(status_code=400, detail="sql 不能为空")
    if not database:
        raise HTTPException(status_code=400, detail="database 不能为空")

    data_scope_header: str | None = None
    topic_id = str(request.topic_id or "").strip()
    if topic_id:
        data_scope_header = _resolve_topic_data_scope_header(topic_id, context=context)

    try:
        return await execute_readonly_query(
            sql,
            database,
            engine=request.engine,
            limit=request.limit,
            timeout_seconds=request.timeout_seconds,
            data_scope_header=data_scope_header,
        )
    except QueryProxyConfigError as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    except QueryProxyUpstreamError as exc:
        raise HTTPException(status_code=exc.status_code, detail=str(exc)) from exc


def _resolve_topic_data_scope_header(topic_id: str, *, context: dict[str, str]) -> str:
    from core.data_scope import encode_scope_header, normalize_data_scope

